function openFromList(e) {
  state.sel = e;
  // keep the cursor in sync with what's open, so the ◀ ▶ buttons (and ↑/↓)
  // step from THIS entry — not from wherever the cursor last was
  const at = state.visible.findIndex(x => x.id === e.id);
  if (at >= 0) state.cursor = at;
  renderEntry(e);
  markActive();
}
function markActive() {
  const eid = state.sel && state.sel.id;
  listEl.querySelectorAll('.lrow.active').forEach(r => r.classList.remove('active'));
  if (eid) {
    const row = listEl.querySelector(`.lrow[data-eid="${CSS.escape(eid)}"]`);
    if (row) row.classList.add('active');
  }
  document.querySelectorAll('.trow.active').forEach(r => r.classList.remove('active'));
  if (eid) {
    // Library cards have no tree row of their own — light up their group instead.
    // Synthetic collection nodes are type 'book'/'volume', so detect them by
    // their NAV- file prefix (same test as renderEntry).
    let markId = eid;
    const sel = state.sel;
    const selIsNav = sel && sel.file && sel.file.startsWith('NAV-');
    if (sel && !selIsNav && sel._navigation && sel._navigation.primaryPath && sel._navigation.primaryPath.length) {
      markId = sel._navigation.primaryPath[sel._navigation.primaryPath.length - 1];
    }
    const trow = document.querySelector(`.trow[data-eid="${CSS.escape(markId)}"]`);
    if (trow) trow.classList.add('active');
  }
}

