/* ================= keyboard ================= */
const hintsEl = $('hints'), helpBtn = $('helpBtn');
function toggleHints(show) {
  const want = show !== undefined ? !!show : hintsEl.hidden;
  hintsEl.hidden = !want;
  hintsEl.classList.toggle('force-show', want);
  helpBtn.setAttribute('aria-expanded', String(want));
}
helpBtn.addEventListener('click', () => toggleHints());
document.addEventListener('keydown', ev => {
  if (ev.key === 'Escape' && !hintsEl.hidden) {
    toggleHints(false);
    return;
  }
  if (document.body.classList.contains('rand-mode')) return;
  const mod = ev.metaKey || ev.ctrlKey;
  if (mod && ev.key.toLowerCase() === 'k') {
    ev.preventDefault();
    if ($('cols').classList.contains('listClosed')) toggleCol('list');
    searchEl.focus(); searchEl.select();
    return;
  }
  if (mod && ev.key === '\\' ) {
    ev.preventDefault(); toggleCol('tree'); return;
  }
  if (mod && ev.key === '1') {
    ev.preventDefault(); toggleCol('list'); return;
  }
  if (mod && ev.shiftKey && ev.key.toLowerCase() === 'c') {
    ev.preventDefault();
    if (state.sel) copyEntry(state.sel);
    return;
  }
  // ⌘C untouched — native copy when text is selected.
  // never intercept keys when the user is typing in any text field (search, notes draft, editor)
  if (ev.target === searchEl) return; // typing: arrows edit the caret
  const tag = ev.target && ev.target.tagName;
  if (tag === 'TEXTAREA' || tag === 'INPUT' || (ev.target && ev.target.isContentEditable)) return;
  if (ev.key === 'ArrowDown' || ev.key === 'ArrowUp') {
    ev.preventDefault();
    stepEntry(ev.key === 'ArrowDown' ? 1 : -1);
  } else if (ev.key === 'Enter') {
    const e = state.visible[state.cursor >= 0 ? state.cursor : 0];
    if (e) openFromList(e);
  }
});

/* step through the current list (used by ↑/↓ keys and the ◀ ▶ buttons) */
function stepEntry(d) {
  if (!state.visible.length) return;
  state.cursor = Math.min(Math.max(state.cursor + d, 0), state.visible.length - 1);
  const e = state.visible[state.cursor];
  if (e) {
    openFromList(e);
    const row = listEl.querySelector(`.lrow[data-eid="${CSS.escape(e.id)}"]`);
    if (row) row.scrollIntoView({ block: 'nearest' });
  }
}

