  const _origCollectCh = collectCh;
  collectCh = function(ch, out) {
    const its = itemsOf.get(ch.file) || [];
    if (its.length) { for (const it of its) out.push(it); }
    else if (ch.file && ch.file.startsWith('NAV-')) {
      for (const sub of (chaptersOf.get(ch.file) || [])) out.push(sub);
    }
    for (const s of (sectionsOf.get(ch.file) || [])) _origCollectCh(s, out);
  };

