/* RANDOMISER VIEW                                                   */
(function () {
'use strict';
const MODEL = window.FCRandomizer.create(window.randData, window.wikiData);
const RBOOKS = MODEL.books;
const $r = id => document.getElementById(id);
const BIDX = new Map(); RBOOKS.forEach((b, bi) => BIDX.set(b.id, bi));
const TOTAL = RBOOKS.reduce((a, b) => a + b.e.length, 0);
const FLAT = [], GPOS = new Map(), NIDX = [];
RBOOKS.forEach((b, bi) => {
  const m = {};
  b.e.forEach((e, ei) => { m[e.n] = ei; GPOS.set(bi + ':' + ei, FLAT.length); FLAT.push([bi, ei]); });
  NIDX.push(m);
});
const FAV_KEY = 'flourishing_favs';

/* wiki id lookup for inline references (E10 -> E010 etc.) */
const WIDX_NORM = {};
const WTITLE = {};
for (const d of window.wikiData) {
  WTITLE[d.id] = d.title;
  const m = /^([A-Z]+)0*(\d+)$/.exec(d.id);
  if (m) WIDX_NORM[m[1] + String(+m[2])] = d.id;
}
function linkifyRefs(s) {
  return s.replace(/([A-Z]{1,3}\d{1,4})/g, (m2, ref) => {
    const wid = WIDX_NORM[ref];
    return wid ? '<a class="wlink" data-wiki="' + wid + '" title="Open ' + wid + ' in the Library">' + ref + '</a>' : ref;
  });
}
/* title -> wiki id map, for linking bolded concept names in parallels */
const WTITLE_ID = {};
const WID_ID = {};
const WFILE_ID = {};
for (const d of window.wikiData) {
  if (d.title && !(d.title in WTITLE_ID)) WTITLE_ID[d.title] = d.id;
  if (d.id) WID_ID[d.id] = d.id;
  if (d.file) WFILE_ID[d.file] = d.id;
}
function resc(s) {
  return String(s).replace(/&/g, '&' + 'amp;').replace(/</g, '&' + 'lt;')
    .replace(/>/g, '&' + 'gt;').replace(/"/g, '&' + 'quot;');
}
function rmd(s) {
  let out = resc(s);
  const exts = [];
  out = out.replace(/\[([^\]]+)\]\((https?:[^)\s]+)\)/g, (m2, txt, url) => {
    exts.push('<a class="ext" href="' + url + '" target="_blank" rel="noopener">' + txt + '</a>');
    return '\u0000' + (exts.length - 1) + '\u0000';
  });
  /* convert every **bold phrase** in a parallels item into a wiki link when it matches a title */
  out = out.replace(/\*\*(.+?)\*\*/g, (m2, name) => {
    const wid = WTITLE_ID[name] || WID_ID[name] || WFILE_ID[name];
    const esc = resc(name);
    if (wid) return '<a class="wlink" data-wiki="' + resc(wid) + '" title="Open ' + resc(wid) + ' in the Library">' + esc + '</a>';
    return '<strong>' + esc + '</strong>';
  });
  /* linkify principle references, but only inside (Operationalises: ...) parens */
  out = out.replace(/\((Operationalises:[^)]*)\)/g, (m2, inner) => '(' + linkifyRefs(inner) + ')');
  return out.replace(/\u0000(\d+)\u0000/g, (m2, i) => exts[+i]);
}

function renderPrincipleBody(src) {
  return window.fcReadingContent(src).split(/\n\s*\n/).filter(s => s.trim()).map(block => {
    let out = rmd(block);
    out = out.replace(/\*For example:\*/g, '<em>For example:</em>');
    const ref = /^\([\s\S]*\)$/.test(block.trim());
    // Tag the authored write-up sections so they carry their own visual hierarchy
    // instead of blending into the principle body.
    const cls = /^\*\*Plain words/.test(block.trim()) ? ' class="fc-plain"'
      : /^\*For example:\*/.test(block.trim()) ? ' class="fc-example"'
      : (ref ? ' class="principle-source"' : '');
    return '<p' + cls + '>' + out.replace(/\n/g, '<br>') + '</p>';
  }).join('');
}
function opRefsOf(x) {
  const m2 = /\((Operationalises:[^)]*)\)/.exec(x);
  if (!m2) return [];
  const ids = (m2[1].match(/[A-Z]{1,3}\d{1,4}/g) || [])
    .map(r => WIDX_NORM[r]).filter(Boolean);
  return [...new Set(ids)];
}
function plain(s) {
  return s.replace(/\*\*/g, '').replace(/\[([^\]]+)\]\((https?:[^)\s]+)\)/g, '$1 ($2)');
}
function volShort(b) { return b.vol.split(' \u2014 ')[0]; }
function bookShort(b) { return b.book.replace(/^Book [IVXLC]+ \u2014 /, ''); }

/* ---------- state ---------- */
let bookFilter = -1, layerFilter = '', pool = [], bag = [], lastIdx = -1;
let selectedBooks = new Set(MODEL.categories.map(c => c.index)), enabledTypes = new Set();
let sessionHist = [], histPos = -1, current = null, savedMode = false;
let storageOk = true, lastTab = '';
let favs = loadFavs();

/* ---------- favourites ---------- */
function loadFavs() {
  try {
    const raw = FC_LS.getItem(FAV_KEY);
    const arr = raw ? JSON.parse(raw) : [];
    if (Array.isArray(arr)) return new Set(arr.filter(x => typeof x === 'string'));
  } catch (e) { storageOk = false; }
  return new Set();
}
function saveFavs() {
  try { FC_LS.setItem(FAV_KEY, JSON.stringify([...favs])); }
  catch (e) { storageOk = false; if (savedMode) render(); }
}
function favId(bi, ei) {
  const e = RBOOKS[bi].e[ei];
  return e.wiki ? 'wiki:' + encodeURIComponent(e.w) : RBOOKS[bi].id + '-p' + e.n;
}
function resolveId(id) {
  if (id.startsWith('wiki:')) {
    let target;
    try { target = decodeURIComponent(id.slice(5)); } catch (_) { return null; }
    for (let bi = MODEL.categoryCount; bi < RBOOKS.length; bi++) {
      const ei = RBOOKS[bi].e.findIndex(e => e.w === target);
      if (ei >= 0) return [bi, ei];
    }
    return null;
  }
  const m = /^(.+)-p(\d+)$/.exec(id);
  if (!m) return null;
  const bi = BIDX.get(m[1]);
  if (bi === undefined) return null;
  const ei = NIDX[bi][+m[2]];
  if (ei === undefined) return null;
  return [bi, ei];
}
function toggleFav() {
  if (!current) return;
  const id = favId(current[0], current[1]);
  if (favs.has(id)) favs.delete(id); else favs.add(id);
  saveFavs();
  updateFavUI();
  const fb = $r('favBtn');
  if (fb && current) {
    const on = favs.has(favId(current[0], current[1]));
    fb.setAttribute('aria-pressed', on ? 'true' : 'false');
    fb.textContent = on ? '★ Saved' : '☆ Save';
  }
}
function updateFavUI() {
  $r('savedCount').textContent = favs.size;
  if (bookFilter === -2) {
    buildPool();
    if (savedMode) renderSaved();
    else if (pool.length === 0) { current = null; render(); }
    else if (current && !favs.has(favId(current[0], current[1]))) draw();
    else render();
  }
}

/* ---------- pool & draw ---------- */
function buildPool() {
  pool = [];
  RBOOKS.forEach((b, bi) => b.e.forEach((e, ei) => {
    if (window.FCRandomizer.matches(e, selectedBooks, enabledTypes, MODEL.categoryCount, layerFilter) &&
        (bookFilter !== -2 || favs.has(favId(bi, ei)))) pool.push([bi, ei]);
  }));
  bag = []; lastIdx = -1;
  $r('poolNote').textContent = pool.length
    ? pool.length.toLocaleString() + ' in the current pool' + (bookFilter === -2 ? ' · saved only' : '') + ' \u00b7 no repeats until it cycles'
    : 'No entries in the current pool';
  const mixed = enabledTypes.size > 0;
  document.querySelector('.draw-label').textContent = mixed ? 'Draw an entry' : 'Draw a principle';
  $r('drawBtn').setAttribute('aria-label', mixed ? 'Draw an entry' : 'Draw a principle');
  $r('drawBtn').disabled = pool.length === 0;
  $r('todayBtn').disabled = pool.length === 0;
  $r('todayBtn').textContent = mixed ? "Today’s entry" : "Today’s principle";
  $r('todayBtn').title = 'The same entry for this selection on the same UTC day';
  $r('randSub').textContent = pool.length.toLocaleString() + ' eligible entries · ' +
    selectedBooks.size + ' of ' + MODEL.categoryCount + ' categories';
}
function shuffle(arr) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}
function drawIndex() {
  if (bag.length === 0) {
    bag = shuffle(pool.map((_, i) => i));
    if (pool.length > 1 && bag[bag.length - 1] === lastIdx) {
      const k = Math.floor(Math.random() * (bag.length - 1));
      [bag[bag.length - 1], bag[k]] = [bag[k], bag[bag.length - 1]];
    }
  }
  return bag.pop();
}
function draw() {
  if (pool.length === 0) { current = null; savedMode = false; renderEmpty(); return; }
  const i = drawIndex();
  lastIdx = i;
  showEntry(pool[i][0], pool[i][1]);
}
function showEntry(bi, ei) {
  sessionHist = sessionHist.slice(0, histPos + 1);
  sessionHist.push([bi, ei]);
  histPos = sessionHist.length - 1;
  current = [bi, ei];
  savedMode = false;
  render();
}
function navHistory(dir) {
  const np = histPos + dir;
  if (np < 0 || np >= sessionHist.length) return;
  histPos = np;
  current = sessionHist[histPos];
  render();
}
function todaysPrinciple() {
  if (!pool.length) return;
  const days = Math.floor(Date.now() / 86400000);
  const seed = Math.imul(days, 2654435761) >>> 0;
  const [bi, ei] = pool[seed % pool.length];
  showEntry(bi, ei);
}

/* ---------- render ---------- */
function render() {
  if (savedMode) { renderSaved(); return; }
  if (!current) { renderEmpty(); return; }
  const [bi, ei] = current;
  const book = RBOOKS[bi], entry = book.e[ei];
  const poolPos = pool.findIndex(([b, e]) => b === bi && e === ei);
  const pos = poolPos >= 0 ? poolPos + 1 : GPOS.get(bi + ':' + ei) + 1;
  const ofTotal = poolPos >= 0 ? pool.length : TOTAL;
  const kind = entry.kind.charAt(0).toUpperCase() + entry.kind.slice(1);

  const parts = [];
  parts.push('<div class="card-meta">');
  if (entry.wiki) parts.push('<div class="eyebrow">' + resc(kind) +
    (entry.categories.size ? ' · ' + resc([...entry.categories].map(i => MODEL.categories[i].label).join(' · ')) : ' · Shared library') + '</div>');
  else parts.push('<div class="eyebrow"><a class="wlink" data-wiki="' + resc(book.volFile) + '">' +
    resc(book.vol) + '</a> \u00b7 <a class="wlink" data-wiki="' + resc(book.bookFile) + '">' +
    resc(book.book) + '</a>' +
    (entry.c ? '<br><span class="layername">' + resc(entry.c) + '</span>' : '') + '</div>');
  parts.push('<div class="meta-right"><span class="counter">Pool position ' +
    pos.toLocaleString() + ' of ' + ofTotal.toLocaleString() + '</span>' +
    '<button class="fav-btn" id="favBtn" type="button" aria-pressed="false">\u2606 Save</button></div>');
  parts.push('</div>');
  parts.push('<div class="principle-num">' + (entry.wiki ? resc(kind) : entry.w ? resc(entry.w) : 'No. ' + entry.n) + '</div>');
  parts.push('<h2 class="principle-title">' + rmd(entry.t) + '</h2>');
  parts.push('<div class="principle-text' + (entry.wiki || entry.fresh ? ' art' : '') + '">' +
    (entry.wiki || entry.fresh ? window.fcWiki.renderMarkdown(window.fcReadingContent(entry.x)) : renderPrincipleBody(entry.x)) + '</div>');

  const tabs = [];
  if (entry.p && entry.p.length) tabs.push(['psych', 'Psychology', entry.p, false]);
  if (entry.f && entry.f.length) tabs.push(['phil', 'Philosophy', entry.f, false]);
  if (entry.r && entry.r.length) tabs.push(['practice', 'Practice', entry.r, true]);
  if (tabs.length) {
    if (!tabs.some(t => t[0] === lastTab)) lastTab = tabs[0][0];
    parts.push('<div class="tabs">');
    parts.push('<div class="tab-btns" role="tablist" aria-label="Companion layers">');
    tabs.forEach(t => {
      const sel = t[0] === lastTab;
      parts.push('<button class="tab-btn" role="tab" id="tab-' + t[0] + '" aria-selected="' + sel +
        '" tabindex="' + (sel ? 0 : -1) + '" data-tab="' + t[0] + '" aria-controls="panel-' + t[0] + '">' +
        t[1] + ' (' + t[2].length + ')</button>');
    });
    parts.push('</div>');
    tabs.forEach(t => {
      const hidden = t[0] !== lastTab;
      parts.push('<div class="tab-panel" role="tabpanel" id="panel-' + t[0] + '" aria-labelledby="tab-' +
        t[0] + '"' + (hidden ? ' hidden' : '') + '>');
      if (entry.fresh) parts.push('<div class="art">' +
        window.fcWiki.renderMarkdown(t[3] ? t[2].join('\n\n') : t[2].map(it => '- ' + it).join('\n')) + '</div>');
      else if (t[3]) parts.push(t[2].map(it => '<p class="practice-text">' + rmd(it) + '</p>').join(''));
      else parts.push('<ul>' + t[2].map(it => '<li>' + rmd(it) + '</li>').join('') + '</ul>');
      parts.push('</div>');
    });
    parts.push('</div>');
  }
  const opRefs = opRefsOf(entry.x);
  if (opRefs.length) {
    parts.push('<div class="op-section"><div class="op-head">Operationalises</div><ul class="op-list">');
    for (const wid of opRefs) {
      parts.push('<li><a class="wlink" data-wiki="' + wid + '"><span class="op-id">' + wid +
        '</span><span class="op-title">' + resc(WTITLE[wid] || '') + '</span></a></li>');
    }
    parts.push('</ul></div>');
  }
  parts.push('<div class="card-footer"><button class="copy-btn" id="copyBtn" type="button">Copy text</button>' +
    (entry.w ? '<button class="wiki-open-btn" id="openWikiBtn" type="button">Open in Library →</button>' +
      '<button class="graph-open-btn" id="openGraphBtn" type="button">Open in Graph →</button>' : '') +
    '</div>');

  if (!entry.wiki && window.fcAuthoredHTML && !/^(?:#{1,6}\s+|\*\*)Plain words/im.test(entry.x)) parts.push(window.fcAuthoredHTML(entry.w, entry.x));
  parts.push(window.fcReflectionHTML(entry.w, entry.t, entry.x));
  const inner = $r('cardInner');
  inner.innerHTML = parts.join('');
  inner.style.animation = 'none';
  void inner.offsetHeight;
  inner.style.animation = '';

  const fb = $r('favBtn');
  if (fb) {
    const on = favs.has(favId(bi, ei));
    fb.setAttribute('aria-pressed', on ? 'true' : 'false');
    fb.textContent = on ? '\u2605 Saved' : '\u2606 Save';
    fb.addEventListener('click', toggleFav);
  }
  const ow = $r('openWikiBtn');
  if (ow) ow.addEventListener('click', () => window.fcWiki.open(entry.w));
  const og = $r('openGraphBtn');
  if (og) og.addEventListener('click', () => {
    // same Open-in-Graph path the Library mini-map uses — switches view,
    // turns the entry's kind on, centres and selects it
    if (window.fcGraph && window.fcGraph.focus) window.fcGraph.focus(entry.w);
  });
  const tl = inner.querySelector('.tab-btns');
  if (tl) {
    tl.addEventListener('click', ev => {
      const b = ev.target.closest('.tab-btn');
      if (b) activateTab(b);
    });
  }
  $r('copyBtn').addEventListener('click', copyCurrent);
  $r('prevBtn').disabled = histPos <= 0;
  $r('nextBtn').disabled = histPos >= sessionHist.length - 1;
  $r('srStatus').textContent = kind + ' ' + entry.n + ': ' + plain(entry.t) + '. ' + book.book + '.';
  document.title = plain(entry.t) + ' \u00b7 The Flourishing Compendium';
}
function activateTab(btn) {
  const key = btn.dataset.tab;
  lastTab = key;
  const inner = $r('cardInner');
  inner.querySelectorAll('.tab-btn').forEach(b => {
    const sel = b.dataset.tab === key;
    b.setAttribute('aria-selected', sel);
    b.tabIndex = sel ? 0 : -1;
  });
  inner.querySelectorAll('.tab-panel').forEach(p => { p.hidden = p.id !== 'panel-' + key; });
}
function renderEmpty() {
  const inner = $r('cardInner');
  if (bookFilter === -2) {
    inner.innerHTML = '<p class="saved-empty">No saved entries match these filters. Save an entry, enable its content type, or broaden your category and layer selection.</p>';
  } else {
    inner.innerHTML = '<p class="saved-empty">No entries match these filters. Select at least one category, choose All layers, or enable another content type.</p>';
  }
  $r('prevBtn').disabled = true;
  $r('nextBtn').disabled = true;
}
function renderSaved() {
  const items = [...favs].map(resolveId).filter(Boolean);
  const parts = ['<div class="saved-panel">'];
  parts.push('<div class="saved-head"><h2>Saved collection (' + items.length + ')</h2>');
  parts.push('<div class="saved-actions">');
  parts.push('<button class="rbtn" id="drawSavedBtn" type="button">Draw from saved</button>');
  parts.push('<button class="rbtn" id="exportMdBtn" type="button">Export Markdown</button>');
  parts.push('<button class="rbtn" id="exportJsonBtn" type="button">Export JSON</button>');
  parts.push('</div></div>');
  if (!storageOk) parts.push('<p class="saved-note">Storage is unavailable in this browser \u2014 saved principles last for this session only.</p>');
  if (!items.length) {
    parts.push('<p class="saved-empty">Nothing saved yet. Tap the \u2606 Save button on a principle, or press F.</p>');
  } else {
    parts.push('<ul class="saved-list">');
    items.forEach(([bi, ei]) => {
      const b = RBOOKS[bi], e = b.e[ei];
      parts.push('<li class="saved-item" data-bi="' + bi + '" data-ei="' + ei + '" tabindex="0">');
      parts.push('<button class="s-remove" data-id="' + resc(favId(bi, ei)) + '" type="button" aria-label="Remove">\u2715</button>');
      parts.push('<div><div class="s-title">' + (e.w ? resc(e.w) + ' \u00b7 ' : '') + rmd(e.t) + '</div>');
      parts.push('<div class="s-meta">' + resc(volShort(b) + ' \u00b7 ' + bookShort(b)) +
        (e.c ? ' \u00b7 ' + resc(e.c) : '') + '</div></div>');
      parts.push('</li>');
    });
    parts.push('</ul>');
  }
  parts.push('</div>');
  const inner = $r('cardInner');
  inner.innerHTML = parts.join('');
  inner.style.animation = 'none'; void inner.offsetHeight; inner.style.animation = '';
  inner.querySelectorAll('.saved-item').forEach(li => {
    li.addEventListener('click', ev => {
      if (ev.target.closest('.s-remove')) return;
      showEntry(+li.dataset.bi, +li.dataset.ei);
    });
  });
  inner.querySelectorAll('.s-remove').forEach(btn => {
    btn.addEventListener('click', () => {
      favs.delete(btn.dataset.id);
      saveFavs();
      updateFavUI();
      renderSaved();
    });
  });
  const ds = $r('drawSavedBtn');
  if (ds) ds.addEventListener('click', () => {
    bookFilter = -2;
    savedMode = false;
    buildPool();
    draw();
  });
  const em = $r('exportMdBtn'); if (em) em.addEventListener('click', () => exportFavs('md'));
  const ej = $r('exportJsonBtn'); if (ej) ej.addEventListener('click', () => exportFavs('json'));
  $r('prevBtn').disabled = true;
  $r('nextBtn').disabled = true;
}

/* ---------- copy & export ---------- */
function copyCurrent() {
  if (!current) return;
  const [bi, ei] = current;
  const book = RBOOKS[bi], entry = book.e[ei];
  let out = (entry.w ? entry.w : 'Principle ' + entry.n) + ' \u2014 ' + plain(entry.t) + '\n' +
    'Book: ' + book.vol + ' \u00b7 ' + book.book + (entry.c ? ' (' + entry.c + ')' : '') + '\n\n' +
    plain(entry.x);
  if (entry.r && entry.r.length) out += '\n\nPractice:\n' + entry.r.map(s => '- ' + plain(s)).join('\n');
  if (entry.p && entry.p.length) out += '\n\nPsychological parallels:\n' + entry.p.map(s => '- ' + plain(s)).join('\n');
  if (entry.f && entry.f.length) out += '\n\nPhilosophical parallels:\n' + entry.f.map(s => '- ' + plain(s)).join('\n');
  const btn = $r('copyBtn');
  const done = () => { btn.textContent = 'Copied'; setTimeout(() => { btn.textContent = 'Copy text'; }, 1600); };
  const fail = () => { btn.textContent = 'Copy failed \u2014 select the text manually'; setTimeout(() => { btn.textContent = 'Copy text'; }, 2600); };
  if (navigator.clipboard && navigator.clipboard.writeText) {
    const timeout = new Promise(res => setTimeout(() => res('timeout'), 1200));
    Promise.race([navigator.clipboard.writeText(out), timeout]).then(v => {
      if (v === 'timeout') fallbackCopy(out, done, fail); else done();
    }, () => fallbackCopy(out, done, fail));
  } else fallbackCopy(out, done, fail);
}
function fallbackCopy(text, done, fail) {
  const ta = document.createElement('textarea');
  ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
  document.body.appendChild(ta); ta.focus(); ta.select();
  let ok = false;
  try { ok = document.execCommand('copy'); } catch (e) { }
  document.body.removeChild(ta);
  if (ok) done(); else fail();
}
function exportFavs(fmt) {
  const items = [...favs].map(resolveId).filter(Boolean)
    .map(([bi, ei]) => ({ book: RBOOKS[bi], entry: RBOOKS[bi].e[ei] }));
  if (!items.length) return;
  let content, name, mime;
  if (fmt === 'json') {
    content = JSON.stringify(items.map(({ book, entry }) => ({
      id: entry.wiki ? 'wiki:' + encodeURIComponent(entry.w) : book.id + '-p' + entry.n, wikiId: entry.w || undefined,
      volume: book.vol, book: book.book, layer: entry.c, number: entry.n,
      title: entry.t, text: entry.x, psychology: entry.p, philosophy: entry.f, practice: entry.r
    })), null, 2);
    name = 'flourishing-principles.json'; mime = 'application/json';
  } else {
    content = '# Saved Principles of Flourishing\n\n' + items.map(({ book, entry }) =>
      '## ' + book.vol + ' \u00b7 ' + book.book + (entry.c ? ' \u2014 ' + entry.c : '') + '\n\n' +
      '### ' + (entry.w || 'No. ' + entry.n) + '. ' + entry.t + '\n\n' + entry.x +
      (entry.r && entry.r.length ? '\n\n**Practice**\n\n' + entry.r.map(s => '- ' + s).join('\n') : '') +
      (entry.p && entry.p.length ? '\n\n**Psychological parallels**\n\n' + entry.p.map(s => '- ' + s).join('\n') : '') +
      (entry.f && entry.f.length ? '\n\n**Philosophical parallels**\n\n' + entry.f.map(s => '- ' + s).join('\n') : '')
    ).join('\n\n---\n\n');
    name = 'flourishing-principles.md'; mime = 'text/markdown';
  }
  const blob = new Blob([content], { type: mime });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob); a.download = name;
  document.body.appendChild(a); a.click(); a.remove();
  setTimeout(() => URL.revokeObjectURL(a.href), 4000);
}

/* ---------- search ---------- */
let HAY = null;
function buildHay() {
  HAY = [];
  RBOOKS.forEach((b, bi) => b.e.forEach((e, ei) => {
    HAY.push([((e.w || '') + ' ' + e.t + ' ' + e.x + ' ' + e.p.join(' ') + ' ' + e.f.join(' ') + ' ' + e.r.join(' ')).toLowerCase(), bi, ei]);
  }));
}
function runSearch(q) {
  q = q.trim().toLowerCase();
  const out = $r('searchResults');
  out._first = null;
  if (q.length < 2) {
    out.innerHTML = '<p class="search-empty">Type at least two letters.</p>';
    return;
  }
  if (!HAY) buildHay();
  const hits = [];
  const eligible = new Set(pool.map(([bi, ei]) => bi + ':' + ei));
  for (let i = 0; i < HAY.length && hits.length < 40; i++) {
    if (eligible.has(HAY[i][1] + ':' + HAY[i][2]) && HAY[i][0].includes(q)) hits.push(HAY[i]);
  }
  if (!hits.length) {
    out.innerHTML = '<p class="search-empty">No entries in the current selection match \u201C' + resc(q) + '\u201D.</p>';
    return;
  }
  out._first = hits[0];
  out.innerHTML = hits.map(h => {
    const b = RBOOKS[h[1]], e = b.e[h[2]];
    return '<div class="sr-item" data-bi="' + h[1] + '" data-ei="' + h[2] + '" tabindex="0">' +
      '<div class="sr-t">' + (e.w ? resc(e.w) + ' \u00b7 ' : '') + rmd(e.t) + '</div>' +
      '<div class="sr-m">' + resc(volShort(b) + ' \u00b7 ' + bookShort(b) + (e.c ? ' \u00b7 ' + e.c : '')) + '</div></div>';
  }).join('');
  out.querySelectorAll('.sr-item').forEach(it => {
    it.addEventListener('click', () => { closeSearch(); showEntry(+it.dataset.bi, +it.dataset.ei); });
    it.addEventListener('keydown', ev => {
      if (ev.key === 'Enter') { ev.preventDefault(); closeSearch(); showEntry(+it.dataset.bi, +it.dataset.ei); }
    });
  });
}
function openSearch() {
  $r('searchDialog').showModal();
  const inp = $r('searchInput');
  inp.value = ''; inp.focus();
  const res = $r('searchResults');
  res._first = null;
  res.innerHTML = '<p class="search-empty">Type at least two letters.</p>';
}
function closeSearch() { $r('searchDialog').close(); }

/* ---------- selects ---------- */
function rebuildBookOptions() {
  let volume = '';
  $r('categoryOptions').innerHTML = '<legend class="sr-only">Draw from categories</legend>' + MODEL.categories.map(c => {
    let group = '';
    if (c.volume !== volume) { volume = c.volume; group = '<div class="category-group">' + resc(volume) + '</div>'; }
    return group + '<label class="category-option"><input type="checkbox" value="' + c.index +
      '" checked><span>' + resc(c.label) + '</span><span class="category-count">' + c.count + '</span></label>';
  }).join('');
  updateCategorySummary();
}
function updateCategorySummary() {
  const labels = MODEL.categories.filter(c => selectedBooks.has(c.index)).map(c => c.label);
  $r('categorySummary').textContent = labels.length === MODEL.categoryCount ? 'All categories'
    : labels.length === 0 ? 'No categories selected' : labels.length <= 2 ? labels.join(' + ') : labels.length + ' categories selected';
}
function filtersChanged() {
  bookFilter = -1;
  savedMode = false;
  current = null;
  sessionHist = []; histPos = -1;
  updateCategorySummary();
  rebuildLayerOptions();
  buildPool();
  draw();
}
function rebuildLayerOptions() {
  const sel = $r('layerSelect');
  const prev = layerFilter;
  const seen = new Map();
  RBOOKS.forEach((b, bi) => {
    b.e.forEach(e => {
      if (e.c && window.FCRandomizer.matches(e, selectedBooks, enabledTypes, MODEL.categoryCount, ''))
        seen.set(e.c, (seen.get(e.c) || 0) + 1);
    });
  });
  const opts = ['<option value="">All layers</option>'];
  seen.forEach((count, c) => {
    opts.push('<option value="' + resc(c) + '">' + resc(c) + ' (' + count + ')</option>');
  });
  sel.innerHTML = opts.join('');
  sel.disabled = false;
  if (prev && seen.has(prev)) sel.value = prev;
  else { layerFilter = ''; sel.value = ''; }
}

/* ---------- init ---------- */
function init() {
  updateFavUI();
  rebuildBookOptions();
  rebuildLayerOptions();
  $r('categoryOptions').addEventListener('change', ev => {
    if (!ev.target.matches('input[type="checkbox"]')) return;
    const index = +ev.target.value;
    if (ev.target.checked) selectedBooks.add(index); else selectedBooks.delete(index);
    filtersChanged();
  });
  [['categoryAll', true], ['categoryNone', false]].forEach(([id, checked]) => {
    $r(id).addEventListener('click', () => {
      selectedBooks = checked ? new Set(MODEL.categories.map(c => c.index)) : new Set();
      $r('categoryOptions').querySelectorAll('input').forEach(input => { input.checked = checked; });
      filtersChanged();
    });
  });
  $r('categoryDone').addEventListener('click', () => {
    $r('categorySelect').open = false;
    $r('categorySelect').querySelector('summary').focus();
  });
  document.querySelectorAll('.rand-types input').forEach(input => {
    input.addEventListener('change', () => {
      if (input.checked) enabledTypes.add(input.value); else enabledTypes.delete(input.value);
      filtersChanged();
    });
  });
  document.addEventListener('click', ev => {
    if (!$r('categorySelect').contains(ev.target)) $r('categorySelect').open = false;
  });
  $r('categorySelect').addEventListener('keydown', ev => {
    if (ev.key === 'Escape') {
      ev.preventDefault(); ev.stopPropagation();
      $r('categorySelect').open = false;
      $r('categorySelect').querySelector('summary').focus();
    }
  });
  $r('layerSelect').addEventListener('change', ev => {
    layerFilter = ev.target.value;
    filtersChanged();
  });
  $r('drawBtn').addEventListener('click', draw);
  $r('prevBtn').addEventListener('click', () => navHistory(-1));
  $r('nextBtn').addEventListener('click', () => navHistory(1));
  $r('todayBtn').addEventListener('click', todaysPrinciple);
  $r('savedBtn').addEventListener('click', () => { savedMode = !savedMode; render(); });
  $r('searchBtn').addEventListener('click', openSearch);

  /* wiki links anywhere in the randomiser view (eyebrow, card text, layers) */
  document.addEventListener('click', ev => {
    if (!document.body.classList.contains('rand-mode')) return;
    const a = ev.target.closest('a.wlink[data-wiki], a.wl[data-file]');
    if (a) { ev.preventDefault(); window.fcWiki.open(a.dataset.wiki || a.dataset.file); }
  });

  const dlg = $r('searchDialog');
  dlg.addEventListener('click', ev => { if (ev.target === dlg) dlg.close(); });
  let debounce = null;
  $r('searchInput').addEventListener('input', ev => {
    clearTimeout(debounce);
    debounce = setTimeout(() => runSearch(ev.target.value), 100);
  });
  $r('searchInput').addEventListener('keydown', ev => {
    if (ev.key === 'Enter') {
      ev.preventDefault();
      clearTimeout(debounce);
      runSearch(ev.target.value);
      const first = $r('searchResults')._first;
      if (first) { closeSearch(); showEntry(first[1], first[2]); }
    }
  });

  document.addEventListener('keydown', ev => {
    if (!document.body.classList.contains('rand-mode')) return;
    const t = ev.target;
    if (ev.key === 'Enter' && t.matches('a.wl[data-file]')) {
      ev.preventDefault();
      window.fcWiki.open(t.dataset.file);
      return;
    }
    const typing = t && (t.tagName === 'INPUT' || t.tagName === 'SELECT' || t.tagName === 'TEXTAREA' || t.isContentEditable || t.closest('#categorySelect'));
    if (typing) return;
    if ($r('searchDialog').open) {
      if (ev.key === 'Escape') closeSearch();
      return;
    }
    if (ev.code === 'Space') {
      if (document.activeElement && document.activeElement.tagName === 'BUTTON') return;
      ev.preventDefault();
      draw();
    } else if (ev.key === 'r' || ev.key === 'R') {
      draw();
    } else if (ev.key === 'ArrowLeft') {
      navHistory(-1);
    } else if (ev.key === 'ArrowRight') {
      navHistory(1);
    } else if (ev.key === 'f' || ev.key === 'F' || ev.key === 's' || ev.key === 'S') {
      toggleFav();
    } else if (ev.key === '/') {
      ev.preventDefault();
      openSearch();
    }
  });

  buildPool();
  draw();
}
init();
})();

