/* ═════════════════════════════════════════════════════════════════
   ACADEMY — Degrees → Modules → curated media
   Curriculum layer over the Flourishing Compendium
   ═════════════════════════════════════════════════════════════════ */
(function(){
'use strict';

/* ---------- Curriculum data (populated by build script) ---------- */
// fcAcademyData is injected earlier in this script by the build. Do NOT reassign here.
// window.fcAcademyData = { ... } // REMOVED — placeholder was overwriting the real data

/* ---------- Utilities ---------- */
const $ = id => document.getElementById(id);
function el(tag, cls, text){ const e=document.createElement(tag); if(cls)e.className=cls; if(text!=null)e.textContent=text; return e; }
function sourceById(id){ return window.fcAcademyData.sources.find(s=>s.source_id===id); }
function moduleById(id){ return window.fcAcademyData.modules[id]; }

/* ---------- State (no persistent storage — sandbox) ---------- */
const A = { view:'home', degree:null, module:null, filters:{q:'',topic:'',level:''}, completed:new Set() };
try { A.completed = new Set(JSON.parse(localStorage.getItem('acadWatched') || '[]')); } catch (e) {}
function saveWatched(){ try { localStorage.setItem('acadWatched', JSON.stringify([...A.completed])); } catch (e) {} }

/* ---------- Navigation ---------- */
function switchView(v){
  // hijack for academy only when called with 'academy'
  if(v==='academy'){
    document.body.classList.remove('rand-mode','wiki-mode','graph-mode');
    document.body.classList.add('academy-mode');
    $('tabRand').classList.remove('active');
    $('tabWiki').classList.remove('active');
    $('tabAcademy').classList.add('active');
    renderAcademy();
    return;
  }
  // hijack for gallery only when called with 'gallery'
  if(v==='gallery'){
    document.body.classList.remove('rand-mode','wiki-mode','graph-mode');
    document.body.classList.add('academy-mode'); // reuse academy-mode container
    $('tabRand').classList.remove('active');
    $('tabWiki').classList.remove('active');
    // Keep the Academy tab active — the gallery is an Academy sub-view
    $('tabAcademy').classList.add('active');
    const tabGallery = $('tabGallery');
    if(tabGallery) tabGallery.classList.add('active');
    renderGallery();
    return;
  }
  if(v==='rand'||v==='wiki'||v==='edit'){ $('tabAcademy').classList.remove('active'); const tg = $('tabGallery'); if(tg) tg.classList.remove('active'); }
  document.body.classList.remove('academy-mode');
}

// Patch the ORIGINAL switchView (window.fcSwitchView) so entering rand/wiki clears academy-mode.
// The original function toggles rand-mode/wiki-mode but doesn't know about academy-mode.
if (window.fcSwitchView) {
  const _origSwitchView = window.fcSwitchView;
  window.fcSwitchView = function(v){
    if (v !== 'academy') {
      document.body.classList.remove('academy-mode');
      const t = document.getElementById('tabAcademy');
      if (t) t.classList.remove('active');
    }
    return _origSwitchView(v);
  };
}
// Also patch the tabRand/tabWiki click listeners by intercepting at capture phase
// (the original listeners call switchView('rand'/'wiki') directly, bypassing fcSwitchView)
['tabRand','tabWiki'].forEach(function(id){
  const btn = document.getElementById(id);
  if (btn) {
    btn.addEventListener('click', function(){
      document.body.classList.remove('academy-mode');
      const t = document.getElementById('tabAcademy');
      if (t) t.classList.remove('active');
    }, true); // capture phase — runs before the original listener
  }
});

/* Render dispatcher */
/* ═════════════════════════════════════════════════════════════════
   GALLERY — 767 primary sources, sorted by host group
   ═════════════════════════════════════════════════════════════════ */
function renderGallery(){
  const root = $('academyRoot');
  if(!root) return;
  root.innerHTML = '';

  const data = window.fcGalleryData || [];
  if(!data.length) { root.appendChild(el('div','acad-empty','Gallery data not loaded.')); return; }

  const wrap = el('div','acad-detail');
  wrap.style.maxWidth = '1200px';
  wrap.style.gap = '16px';

  // Header
  const head = el('div','acad-detail-head');
  const backBtn = el('button','acad-btn ghost','← Academy');
  backBtn.onclick = () => { switchView('academy'); };
  head.appendChild(backBtn);
  head.appendChild(el('h2','acad-detail-title','Flourishing Gallery'));
  wrap.appendChild(head);
  wrap.appendChild(el('p','acad-detail-desc','767 primary sources — thinkers, texts, and research. Sorted by host group: SEP, WIKI, IEP, PMC, Project Gutenberg, Internet Archive, and more.'));

  // Filters
  const fbar = el('div','acad-explorer-filters');
  const search = el('input','acad-explorer-search');
  search.type = 'search';
  search.placeholder = 'Search gallery…';
  const hostSel = el('select','acad-explorer-select');
  const hosts = [...new Set(data.map(d => d.host))];
  const optAll = el('option', null, 'All hosts'); optAll.value = ''; hostSel.appendChild(optAll);
  hosts.forEach(h => { const o = el('option', null, h); o.value = h; hostSel.appendChild(o); });
  const themeSel = el('select','acad-explorer-select');
  const themes = [...new Set(data.map(d => d.theme))];
  const optAllT = el('option', null, 'All themes'); optAllT.value = ''; themeSel.appendChild(optAllT);
  themes.forEach(t => { const o = el('option', null, t); o.value = t; themeSel.appendChild(o); });

  let q = '', host = '', theme = '';
  const list = el('div','gallery-grid');
  let pageSize = 120;

  function makeCard(d){
    const card = el('div','gallery-card');
    card.tabIndex = 0;
    card.setAttribute('role','button');
    card.setAttribute('aria-label','Open: ' + (d.text||''));
    if(d.image) {
      const img = el('img','gallery-card-img');
      img.src = d.image; img.alt = ''; img.loading = 'lazy'; img.onerror = function(){ img.style.display = 'none'; };
      card.appendChild(img);
    }
    const info = el('div','gallery-card-info');
    info.appendChild(el('div','gallery-card-host', d.host || ''));
    info.appendChild(el('div','gallery-card-title', d.text || 'untitled'));
    info.appendChild(el('div','gallery-card-theme', d.theme || ''));
    card.appendChild(info);
    card.onclick = () => { if(d.url) window.open(d.url,'_blank','noopener'); };
    return card;
  }

  function render(){
    list.innerHTML = '';
    const visible = data.filter(d => {
      if(host && d.host !== host) return false;
      if(theme && d.theme !== theme) return false;
      if(q) {
        const hay = (d.text + ' ' + d.theme + ' ' + (d.host_name||'') + ' ' + (d.source_entry||'')).toLowerCase();
        if(!hay.includes(q)) return false;
      }
      return true;
    });

    if(!visible.length){
      list.appendChild(el('div','acad-empty','No results.'));
      return;
    }

    // First page
    visible.slice(0, pageSize).forEach(d => list.appendChild(makeCard(d)));

    // "Load more" pagination for remaining records
    if(visible.length > pageSize){
      const moreWrap = el('div','gallery-more');
      moreWrap.style.cssText = 'grid-column:1/-1;text-align:center;padding:12px;';
      const moreBtn = el('button','acad-btn','Load more (' + (visible.length - pageSize) + ' remaining)');
      moreBtn.onclick = () => {
        pageSize += 120;
        render();
        // Keep the button in view
        requestAnimationFrame(()=>{ moreWrap.scrollIntoView && moreWrap.scrollIntoView({block:'nearest'}); });
      };
      moreWrap.appendChild(moreBtn);
      list.appendChild(moreWrap);
    }
  }

  search.oninput = () => { q = search.value.toLowerCase(); pageSize = 120; render(); };
  hostSel.onchange = () => { host = hostSel.value; pageSize = 120; render(); };
  themeSel.onchange = () => { theme = themeSel.value; pageSize = 120; render(); };

  fbar.appendChild(search);
  fbar.appendChild(hostSel);
  fbar.appendChild(themeSel);
  wrap.appendChild(fbar);
  wrap.appendChild(list);
  root.appendChild(wrap);
  render();
}

function renderAcademy(){
  const root = $('academyRoot');
  if(!root) return;
  root.innerHTML='';
  if(A.view==='sourceExplorer'){ root.appendChild(renderSourceExplorer()); return; }
  if(A.view==='degreeDetail' && A.degree){ root.appendChild(renderDegreeDetail(A.degree)); return; }
  if(A.view==='moduleDetail' && A.module){ root.appendChild(renderModuleDetail(A.module)); return; }
  root.appendChild(renderAcademyHome());
}

/* ---------- Gallery (Degrees overview) ---------- */
function renderAcademyHome(){
  const wrap = el('div');
  const top = el('div','acad-topbar');
  top.appendChild(el('h2','acad-title','The Academy'));
  top.appendChild(el('p','acad-sub','Self-directed study pathways — eight degrees, each composed of modules, each module anchored in curated long-form video by credentialed presenters. Non-accredited; for genuine flourishing.'));

  const actions = el('div','acad-actions');

  // MORE VIDEOS — replaces "Explore all sources" (same target: the 308-source explorer)
  const moreVideosBtn = el('button','acad-btn','MORE VIDEOS');
  moreVideosBtn.title = 'Explore all 308 curated video sources';
  moreVideosBtn.onclick = () => {
    A.view = 'sourceExplorer';
    renderAcademy();
  };
  actions.appendChild(moreVideosBtn);

  // DISCOVERY — opens the 767-source consolidated gallery
  const discoveryBtn = el('button','acad-btn','DISCOVERY');
  discoveryBtn.title = 'Flourishing Gallery — 767 primary sources';
  discoveryBtn.onclick = () => { switchView('gallery'); };
  actions.appendChild(discoveryBtn);

  top.appendChild(actions);
  wrap.appendChild(top);

  // About note
  const about = el('div','acad-sub');
  about.style.padding='12px 0';
  about.textContent = 'The Academy is the instructional sequence over the Learning Library — 308 curated source records drawn from missions M-01 through M-26 and the M-33 audit (verified against all seven eligibility gates). Records carry mission provenance; gate evidence varies by record (some inherit unresolved host-gate or duration questions). Views/likes do not matter. Curriculum status: draft.';
  wrap.appendChild(about);

  // Degree grid
  const grid = el('div','acad-degree-grid');
  for(const deg of window.fcAcademyData.degrees){
    const card = el('div','acad-degree-card'); card.tabIndex=0; card.setAttribute('role','button'); card.setAttribute('aria-label', 'Open degree: ' + deg.title);
    card.appendChild(el('div','acad-degree-icon', deg.icon||'🎓'));
    card.appendChild(el('div','acad-degree-title', deg.title));
    card.appendChild(el('div','acad-degree-desc', deg.description));
    const meta = el('div','acad-degree-meta');
    const chip = el('span','acad-chip', `${(deg.modules||[]).length} modules`);
    meta.appendChild(chip);
    if(deg.status==='draft'){ meta.appendChild(el('span','acad-chip draft','draft')); }
    card.appendChild(meta);
    card.onclick = () => { A.view='degreeDetail'; A.degree=deg.id; renderAcademy(); };
    card.onkeydown = (e)=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); card.onclick(); } };
    grid.appendChild(card);
  }
  wrap.appendChild(grid);
  return wrap;
}


/* ---------- Degree detail ---------- */
function renderDegreeDetail(degId){
  const deg = window.fcAcademyData.degrees.find(d=>d.id===degId);
  if(!deg) return el('div','acad-empty','Degree not found');

  const wrap = el('div','acad-detail');
  const head = el('div','acad-detail-head');
  const t = el('div');
  t.appendChild(el('h2','acad-detail-title',deg.title));
  const back = el('button','acad-btn ghost','← Academy');
  back.onclick = () => { A.view='home'; renderAcademy(); };
  head.appendChild(back);
  head.appendChild(t);
  wrap.appendChild(head);

  wrap.appendChild(el('p','acad-detail-desc',deg.description));
  const meta = el('div','acad-detail-meta');
  meta.appendChild(el('span','acad-chip',`${(deg.modules||[]).length} modules`));
  meta.appendChild(el('span','acad-chip academic','self-directed'));
  if(deg.status==='draft'){ meta.appendChild(el('span','acad-chip draft','draft — some modules lack Mastery-level sources')); }
  wrap.appendChild(meta);

  // Shared opening module note (cleaned: strip internal ticket/agent codes)
  if(deg.openingNote){
    const clean = deg.openingNote.replace(/\s*\(M-\d+[^)]*\)\s*/g,' ').replace(/\s*HOME\d+[^)]*\s*/g,' ').replace(/\s{2,}/g,' ').trim();
    if(clean) wrap.appendChild(el('p','acad-limitation',clean));
  }

  const list = el('div','acad-module-list');
  (deg.modules||[]).forEach((mid,idx)=>{
    const mod = moduleById(mid);
    if(!mod) return;
    list.appendChild(renderModuleCard(mod,idx+1));
  });
  wrap.appendChild(list);

  // Go Further: live-practice discovery cards (per-degree, optional)
  if(deg.goFurther && deg.goFurther.length){
    const gf = el('div','acad-section');
    gf.appendChild(el('div','acad-section-title','Go further — find live practice'));
    const grid = el('div','acad-gf-grid');
    deg.goFurther.forEach(g=>{
      const card = document.createElement('a');
      card.className = 'acad-gf-card';
      card.href = g.url; card.target = '_blank'; card.rel = 'noopener noreferrer';
      const img = document.createElement('img');
      img.src = g.image; img.alt = ''; img.loading = 'lazy';
      img.onerror = function(){ this.style.display = 'none'; };
      card.appendChild(img);
      const body = el('div','acad-gf-body');
      body.appendChild(el('div','acad-gf-title', g.title));
      body.appendChild(el('div','acad-gf-desc', g.description));
      card.appendChild(body);
      grid.appendChild(card);
    });
    gf.appendChild(grid);
    wrap.appendChild(gf);
  }
  return wrap;
}

/* ---------- Module card (in degree list) ---------- */
function renderModuleCard(mod,num){
  const card = el('div','acad-module'); card.tabIndex=0; card.setAttribute('role','button');
  const head = el('div','acad-module-header');
  head.appendChild(el('span','acad-module-num',`Module ${num}`));
  head.appendChild(el('span','acad-module-title',mod.title));
  card.appendChild(head);

  if(mod.question){ card.appendChild(el('p','acad-module-question',mod.question)); }
  const meta = el('div','acad-module-meta');
  if(mod.difficulty){ meta.appendChild(el('span','acad-chip',mod.difficulty)); }
  if(mod.durationHours){ meta.appendChild(el('span','acad-chip',`${mod.durationHours}h`)); }
  card.appendChild(meta);

  if(mod.outcomes && mod.outcomes.length){
    const ol = el('ul','acad-outcomes');
    mod.outcomes.slice(0,3).forEach(o=>ol.appendChild(el('li',null,o)));
    card.appendChild(ol);
  }

  // Required media
  const reqs = (mod.requiredMedia||[]);
  reqs.forEach(m=>{
    const src = sourceById(m.source_id);
    if(!src) return;
    card.appendChild(renderMediaRow(src,m.level));
  });

  if((mod.gaps||[]).length){
    card.appendChild(el('div','acad-limitation',`Gap: ${mod.gaps[0]}`));
  }

  card.onclick = (e)=>{
    if(e.target.closest('.acad-media-row')) return; // let media click pass
    A.view='moduleDetail'; A.module=mod.id; renderAcademy();
  };
  card.style.cursor='pointer';
  return card;
}

/* ---------- Media row ---------- */
function renderMediaRow(src,level){
  const row = el('div','acad-media-row'); row.tabIndex=0; row.setAttribute('role','button'); row.setAttribute('aria-label','Open media: ' + (src.title||''));
  if (src.source_id) { row.dataset.srcId = src.source_id; }
  const isWatched = !!(src.source_id && A.completed.has(src.source_id));
  if (isWatched) row.classList.add('watched');
  const lv = el('span',`acad-media-level${(level||'').toLowerCase()==='mastery'?' mastery':''}${(level||'').toLowerCase()==='advanced'?' advanced':''}`, level||'');
  row.appendChild(lv);
  const info = el('div','acad-media-info');
  info.appendChild(el('div','acad-media-title',src.title||'untitled'));
  info.appendChild(el('div','acad-media-host',[src.presenter,src.host].filter(Boolean).join(' · ')||''));
  row.appendChild(info);
  if(src.duration){ row.appendChild(el('span','acad-media-duration',src.duration)); }
  if (isWatched) row.appendChild(el('span','acad-watched-badge','✓ Watched'));
  row.onclick = (e)=>{ e.stopPropagation(); openSource(src); };
  row.onkeydown = (e)=>{
    if(e.key==='Enter' || e.key===' '){
      e.preventDefault(); e.stopPropagation(); openSource(src);
    }
  };
  return row;
}

function openSource(src){
  if(!src) return;
  const url = src.canonical_url || (src.youtube_id_or_url && /^https?:/.test(src.youtube_id_or_url) ? src.youtube_id_or_url : `https://www.youtube.com/watch?v=${src.youtube_id_or_url}`);
  if(url) openEmbeddedPlayer(src, url);
}

function openEmbeddedPlayer(src, url){
  // Create an overlay with the embedded player, keeping the user inside the site
  closeModal();
  const overlay = el('div','acad-player-overlay');
  overlay.id = 'acadPlayerOverlay';
  const box = el('div','acad-player-box');
  const closeBtn = el('button','acad-player-close','✕');
  closeBtn.setAttribute('aria-label','Close player');
  closeBtn.onclick = ()=> closeModal();
  box.appendChild(closeBtn);
  const head = el('div','acad-player-head');
  head.appendChild(el('h3','acad-player-title',src.title||'Untitled'));
  if(src.presenter || src.host){
    head.appendChild(el('div','acad-player-host',[src.presenter,src.host].filter(Boolean).join(' · ')));
  }
  if(src.duration){ head.appendChild(el('span','acad-player-duration',src.duration)); }
  box.appendChild(head);
  const frame = el('div','acad-player-frame');
  const ytId = extractYouTubeId(url);
  const hasWebOrigin = (location.protocol === 'http:' || location.protocol === 'https:') && location.origin && location.origin !== 'null';
  if(ytId && !hasWebOrigin){
    // Local-file (file://) context: YouTube embeds throw Error 153 (missing HTTP Referer).
    // Fall back to a clean link-out instead of a doomed iframe.
    const msg = el('div','acad-player-fallback');
    msg.appendChild(el('div','acad-player-fallback-title','Open on YouTube'));
    msg.appendChild(el('div','acad-player-fallback-sub','Embedded playback isn\u2019t available in the downloaded file. This video will open on YouTube in a new tab.'));
    const open = document.createElement('a');
    open.href = url;
    open.target = '_blank';
    open.rel = 'noopener noreferrer';
    open.className = 'acad-btn primary';
    open.textContent = 'Play on YouTube \u2197';
    msg.appendChild(open);
    frame.appendChild(msg);
  } else if(ytId){
    const iframe = document.createElement('iframe');
    iframe.src = `https://www.youtube.com/embed/${ytId}?autoplay=1&rel=0&modestbranding=1`;
    iframe.allow = 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share';
    iframe.allowFullscreen = true;
    iframe.referrerPolicy = 'strict-origin-when-cross-origin';
    iframe.title = src.title||'Video player';
    frame.appendChild(iframe);
  } else {
    const msg = el('div','acad-player-fallback','This source is hosted on an external site.');
    const extBtn = el('button','acad-btn primary','Open in new tab');
    extBtn.onclick = ()=>{ window.open(url,'_blank','noopener'); };
    msg.appendChild(extBtn);
    frame.appendChild(msg);
  }
  box.appendChild(frame);
  const foot = el('div','acad-player-foot');
  // 'Open in new tab' removed — redundant with the YouTube fallback's 'Play on YouTube' button
  const doneBtn = el('button','acad-btn primary', A.completed.has(src.source_id)?'✓ Watched':'Mark as watched');
  doneBtn.onclick = ()=>{
    if(A.completed.has(src.source_id)) A.completed.delete(src.source_id);
    else A.completed.add(src.source_id);
    doneBtn.textContent = A.completed.has(src.source_id)?'✓ Watched':'Mark as watched';
    // reflect the change on the media rows in the list behind the player
    document.querySelectorAll('.acad-media-row[data-src-id="' + src.source_id + '"]').forEach(function(r){
      const on = A.completed.has(src.source_id);
      r.classList.toggle('watched', on);
      let b = r.querySelector('.acad-watched-badge');
      if (on && !b) {
        b = document.createElement('span');
        b.className = 'acad-watched-badge';
        b.textContent = '\u2713 Watched';
        r.appendChild(b);
      } else if (!on && b) {
        b.remove();
      }
    });
    saveWatched();
  };
  foot.appendChild(doneBtn);
  box.appendChild(foot);
  overlay.appendChild(box);
  overlay.onclick = (e)=>{ if(e.target===overlay) closeModal(); };
  document.body.appendChild(overlay);
  document.addEventListener('keydown', playerEscHandler);
}
function playerEscHandler(e){ if(e.key==='Escape') closeModal(); }
function closeModal(){
  const ov = document.getElementById('acadPlayerOverlay');
  if(ov){ ov.remove(); document.removeEventListener('keydown', playerEscHandler); }
}
function extractYouTubeId(url){
  if(!url) return null;
  const m = url.match(/(?:youtube\.com\/(?:watch\?v=|embed\/|shorts\/)|youtu\.be\/)([A-Za-z0-9_-]{11})/);
  return m ? m[1] : null;
}

/* ---------- Module detail ---------- */
function renderModuleDetail(modId){
  const mod = moduleById(modId);
  if(!mod) return el('div','acad-empty','Module not found');
  const wrap = el('div','acad-detail');
  if(modId) wrap.dataset.mod = modId; // Psychonaute-inspired per-module palette
  const head = el('div','acad-detail-head');
  const back = el('button','acad-btn ghost','← Degree');
  back.onclick = ()=>{ A.view='degreeDetail'; A.degree=mod.degree_id; renderAcademy(); };
  head.appendChild(back);
  head.appendChild(el('h2','acad-detail-title',mod.title));
  wrap.appendChild(head);

  if(mod.question){ wrap.appendChild(el('p','acad-module-question',mod.question)); }
  if(mod.description){ wrap.appendChild(el('p','acad-detail-desc',mod.description)); }

  // Psychonaute-inspired: module-specific reflection prompt (the "interaction twist")
  const MOD_PROMPTS = {
    'mod-phil-1': 'As you study each source, ask: what habit (hexis) is this cultivating in me?',
    'mod-phil-2': 'For each source, sort what it teaches into: in my control / not in my control.',
    'mod-phil-3': 'After each source, rate it 1-5: does this simplify or complicate the good life?',
    'mod-phil-4': 'For each source, ask: what practical difference would believing this make?',
    'mod-phil-5': 'For each source, ask: what would I do differently if I were radically free?',
    'mod-cont-1': 'For each source, notice: where is effort here, and where is non-action (wu wei)?',
    'mod-cont-2': 'For each source, ask: what perspective am I being invited to shift into?',
    'mod-cont-3': 'For each source, ask: what does this reveal about the nature of suffering (dukkha)?',
    'mod-cont-4': 'For each source, ask: what here is self, and what is not-self?',
    'mod-cont-5': 'For each source, ask: what is being given and received here?',
    'mod-rel-1': 'For each source, ask: who am I because of whom?',
    'mod-rel-2': 'For each source, ask: who cares for whom, and how?',
    'mod-rel-3': 'For each source, ask: what does the face of the Other ask of me?',
    'mod-mind-1': 'For each source, plot it on your own valence/arousal map: pleasant-unpleasant, calm-activated.',
    'mod-mind-2': 'For each source, ask: what is attention being trained to do here?',
    'mod-mind-3': 'For each source, ask: which self is being constructed or deconstructed?',
    'mod-mind-4': 'For each source, ask: what drives this behaviour — autonomy, competence, or relatedness?',
    'mod-wb-1': 'For each source, ask: which element of PERMA does this strengthen?',
    'mod-wb-2': 'For each source, ask: when have I experienced this kind of flow?',
    'mod-wb-3': 'For each source, ask: what makes flourishing collective here, not just individual?',
    'mod-ther-1': 'For each source, ask: what do I really want, and what is stopping me?',
    'mod-ther-2': 'For each source, ask: is this soothing, driving, or threatening?',
    'mod-ther-3': 'For each source, ask: how does this change my relationship to my thoughts?',
    'mod-cap-philosophy': 'Synthesis: weave two sources into one original reflection on practical wisdom.',
    'mod-cap-contemplative': 'Synthesis: compare two contemplative traditions on one shared question.',
    'mod-cap-relational': 'Synthesis: connect two relational thinkers across cultures.',
    'mod-cap-mind': 'Synthesis: link one affective insight with one cognitive insight.',
    'mod-cap-wellbeing': 'Synthesis: apply PERMA to one real situation from your own life.',
    'mod-cap-therapeutic': 'Synthesis: contrast two therapeutic approaches on the same condition.'
  };
  const prompt = MOD_PROMPTS[modId];
  if(prompt){
    const card = el('div','acad-module-prompt');
    card.appendChild(el('div','acad-module-prompt-icon','\u{1F9E0}'));
    card.appendChild(el('div','acad-module-prompt-text',prompt));
    wrap.appendChild(card);
  }

  const meta = el('div','acad-detail-meta');
  if(mod.difficulty){ meta.appendChild(el('span','acad-chip',mod.difficulty)); }
  if(mod.durationHours){ meta.appendChild(el('span','acad-chip',`${mod.durationHours}h`)); }
  wrap.appendChild(meta);

  // Learning outcomes
  if(mod.outcomes && mod.outcomes.length){
    const sec = el('div','acad-section');
    sec.appendChild(el('div','acad-section-title','Learning outcomes'));
    const ol = el('ul','acad-outcomes');
    mod.outcomes.forEach(o=>ol.appendChild(el('li',null,o)));
    sec.appendChild(ol);
    wrap.appendChild(sec);
  }

  // Prerequisites
  if(mod.prerequisites && mod.prerequisites.length){
    const sec = el('div','acad-section');
    sec.appendChild(el('div','acad-section-title','Prerequisites'));
    const ol = el('ul','acad-outcomes');
    mod.prerequisites.forEach(p=>ol.appendChild(el('li',null,p)));
    sec.appendChild(ol);
    wrap.appendChild(sec);
  }

  // Required media (full list)
  const sec = el('div','acad-section');
  sec.appendChild(el('div','acad-section-title','Required media'));
  (mod.requiredMedia||[]).forEach(m=>{
    const src = sourceById(m.source_id);
    if(src) sec.appendChild(renderMediaRow(src,m.level));
  });
  wrap.appendChild(sec);

  // Optional extensions
  if((mod.optionalMedia||[]).length){
    const sec2 = el('div','acad-section');
    sec2.appendChild(el('div','acad-section-title','Optional extensions'));
    mod.optionalMedia.forEach(m=>{
      const src = sourceById(m.source_id);
      if(src) sec2.appendChild(renderMediaRow(src,m.level));
    });
    wrap.appendChild(sec2);
  }

  // Related wiki readings
  if((mod.wiki_readings||[]).length){
    const sec3 = el('div','acad-section');
    sec3.appendChild(el('div','acad-section-title','Related Compendium readings'));
    const ol = el('ul','acad-outcomes');
    mod.wiki_readings.forEach(r=>{
      const li = el('li');
      const a = el('a','art-link',r.title);
      a.tabIndex = 0;
      a.onclick=()=>{ if(window.fcWiki && window.fcWiki.open){ window.fcSwitchView('wiki'); window.fcWiki.open(r.wiki_id); } };
      li.appendChild(a);
      ol.appendChild(li);
    });
    sec3.appendChild(ol);
    wrap.appendChild(sec3);
  }

  // Activity / assessment
  if(mod.activity){
    const sec4 = el('div','acad-section');
    sec4.appendChild(el('div','acad-section-title','Activity'));
    sec4.appendChild(el('p','acad-detail-desc',mod.activity));
    if(mod.rubric){
      const ol = el('ul','acad-outcomes');
      mod.rubric.forEach(r=>ol.appendChild(el('li',null,r)));
      sec4.appendChild(ol);
    }
    wrap.appendChild(sec4);
  }

  // Gaps / limitations
  if((mod.gaps||[]).length){
    const sec5 = el('div','acad-section');
    sec5.appendChild(el('div','acad-section-title','Limitations & gaps'));
    mod.gaps.forEach(g=>sec5.appendChild(el('div','acad-limitation',g)));
    wrap.appendChild(sec5);
  }

  // Completion toggle (checkbox)
  const doneWrap = el('label','acad-complete-toggle');
  const doneCb = el('input');
  doneCb.type = 'checkbox';
  doneCb.checked = A.completed.has(modId);
  doneCb.onchange = ()=>{
    if(A.completed.has(modId)) A.completed.delete(modId);
    else A.completed.add(modId);
  };
  const doneLabel = el('span','acad-complete-label','Mark module complete');
  doneWrap.append(doneCb, doneLabel);
  wrap.appendChild(doneWrap);
  return wrap;
}

/* ---------- Source Explorer ---------- */
function renderSourceExplorer(){
  const wrap = el('div','acad-explorer');
  const head = el('div','acad-detail-head');
  const back = el('button','acad-btn ghost','← Academy');
  back.onclick = ()=>{ A.view='home'; renderAcademy(); };
  head.appendChild(back);
  head.appendChild(el('h2','acad-detail-title','Source Exploration'));
  wrap.appendChild(head);
  wrap.appendChild(el('p','acad-detail-desc','308 curated source records from the Learning Library (M-01–M-26) plus the M-33 audit additions. Later missions (M-12 onward) carry per-gate evidence; earlier records inherit summary-level provenance. Filter by topic, level, or search. Click a source to open it.'));

  // Filters
  const fbar = el('div','acad-explorer-filters');
  const search = el('input','acad-explorer-search');
  search.type='search'; search.placeholder='Search title, presenter, host…'; search.setAttribute('aria-label','Search sources');
  search.value = A.filters.q;
  search.oninput = ()=>{ A.filters.q = search.value.toLowerCase(); renderSourceList(); };
  fbar.appendChild(search);

  const topicSel = el('select','acad-explorer-select');
  // Human-readable topic names (the raw codes are internal and cryptic)
  window.TOPIC_NAMES = {
    'P-AF-84': 'Affect & Emotion',
    'P-AR-122': 'Aristotelian Virtue Ethics',
    'P-AT-78': 'Attention & Cognition',
    'P-B-198': 'Buddhist Philosophy & Practice',
    'P-BP-72': 'Biophysiology & Health',
    'P-CFT-7': 'Compassion-Focused Therapy',
    'P-COG-5': 'Cognitive-Behavioral Therapy',
    'P-COG-83': 'Cognitive Psychology & Rationality',
    'P-D-192': 'Daoist Philosophy',
    'P-EX-113': 'Existentialism & Phenomenology',
    'P-FL-2': 'Flow & Optimal Experience',
    'P-KT-71': 'Kyoto School Philosophy',
    'P-MA-55': 'Mesoamerican Thought',
    'P-MB-10': 'Mindfulness-Based Interventions',
    'P-MD-1': 'Madhyamaka Buddhism',
    'P-MI-12': 'Motivational Interviewing',
    'P-MO-76': 'Motivation & Self-Determination',
    'P-OB-78': 'Physical Performance & Behaviour',
    'P-P-196': 'Pragmatism & Process Thought',
    'P-PPI-83': 'Positive Psychology & Well-Being',
    'P-RE-130': 'Relational Ethics',
    'P-SE-82': 'Self & Identity',
    'P-SO-76': 'Social Cognition & Culture',
    'P-SP-96': 'Spinoza & Early Modern',
    'P-ST-140': 'Stoicism',
    'P-UB-1': 'Ubuntu Philosophy',
    'P-XP-26': 'Hellenistic Ethics',
    'P-YV-132': 'Yoga-Vedanta',
    'Conatus': 'Conatus',
    'Dao': 'Dao',
    'Eudaimonia': 'Eudaimonia',
    'Flow': 'Flow',
    'Impermanence': 'Impermanence',
    'Karma': 'Karma',
    'Nepantla': 'Nepantla',
    'Phronesis': 'Phronesis',
    'Qi': 'Qi',
    'Ubuntu': 'Ubuntu'
  };
  const topics = [...new Set(window.fcAcademyData.sources.map(s=>(s.topic_ids||'').split(',').map(t=>t.trim()).filter(Boolean)).flat())].sort();
  const optAll = el('option',null,'All topics'); optAll.value=''; topicSel.appendChild(optAll);
  topics.forEach(t=>{const o=el('option',null,window.TOPIC_NAMES[t] || t); o.value=t; topicSel.appendChild(o);});
  topicSel.value = A.filters.topic || '';
  topicSel.onchange = ()=>{ A.filters.topic = topicSel.value; renderSourceList(); };
  fbar.appendChild(topicSel);

  const levelSel = el('select','acad-explorer-select');
  const optAllL = el('option',null,'All levels'); optAllL.value=''; levelSel.appendChild(optAllL);
  ['Foundations','Intermediate','Advanced','Mastery','Not stated'].forEach(l=>{const o=el('option',null,l); o.value=l; levelSel.appendChild(o);});
  levelSel.value = A.filters.level || '';
  levelSel.onchange = ()=>{ A.filters.level = levelSel.value; renderSourceList(); };
  fbar.appendChild(levelSel);
  wrap.appendChild(fbar);

  // Grid
  const grid = el('div','acad-source-grid');
  grid.id='acadSourceGrid';
  wrap.appendChild(grid);
  const empty = el('div','acad-empty'); empty.id='acadSourceEmpty'; empty.hidden=true;
  wrap.appendChild(empty);

  function renderSourceList(){
    const grid2 = $('acadSourceGrid'); if(!grid2) return;
    grid2.innerHTML='';
    const q=A.filters.q, topic=A.filters.topic, level=A.filters.level;
    const matches = window.fcAcademyData.sources.filter(s=>{
      if(q){
        const hay=[s.title,s.presenter,s.host,(s.topic_ids||'')].join(' ').toLowerCase();
        if(!hay.includes(q)) return false;
      }
      if(topic){
        const ts=(s.topic_ids||'').split(',').map(t=>t.trim());
        if(!ts.includes(topic)) return false;
      }
      if(level && (s.level||'')!==level) return false;
      return true;
    });
    if(!matches.length){
      $('acadSourceEmpty').hidden=false;
      $('acadSourceEmpty').textContent='No sources match your filters. Clear a filter or search a different term.';
      return;
    }
    $('acadSourceEmpty').hidden=true;
    matches.forEach(s=>grid2.appendChild(renderSourceCard(s)));
  }
  renderSourceList();
  // Re-render after mount — the initial call exits because the grid isn't in the DOM yet.
  const origAppend = wrap.appendChild.bind(wrap);
  wrap.appendChild = (node) => { const r = origAppend(node); return r; };
  // schedule a re-render on next frame after mount
  requestAnimationFrame(() => { if(document.getElementById('acadSourceGrid')) renderSourceList(); });
  return wrap;
}

function renderSourceCard(s){
  const c = el('div','acad-source-card'); c.tabIndex=0; c.setAttribute('role','button'); c.setAttribute('aria-label','Open source: ' + (s.title||''));
  // YouTube thumbnail (if we have a video ID or URL)
  const rawId = s.youtube_id_or_url || '';
  const ytId = extractYouTubeId(rawId) || (/^[A-Za-z0-9_-]{11}$/.test(rawId.trim()) ? rawId.trim() : null);
  if(ytId){
    const thumb = el('img','acad-source-thumb');
    thumb.src = `https://i.ytimg.com/vi/${ytId}/mqdefault.jpg`;
    thumb.alt = ''; thumb.loading = 'lazy';
    thumb.onerror = function(){ thumb.style.display = 'none'; };
    c.appendChild(thumb);
  }
  c.appendChild(el('div','acad-source-title',s.title||'untitled'));
  if(s.presenter) c.appendChild(el('div','acad-source-presenter',s.presenter));
  if(s.host) c.appendChild(el('div','acad-source-host',s.host));
  const meta = el('div','acad-source-meta');
  (s.topic_ids||'').split(',').map(t=>t.trim()).filter(Boolean).slice(0,2).forEach(t=>meta.appendChild(el('span','acad-chip',window.TOPIC_NAMES[t]||t)));
  if(s.level){ meta.appendChild(el('span',`acad-chip${s.level==='Mastery'?' mastery':''}`,s.level)); }
  if(s.duration){ meta.appendChild(el('span','acad-chip',s.duration)); }
  c.appendChild(meta);
  c.onclick = ()=>openSource(s);
  return c;
}

/* ---------- Gallery tab wiring (gallery is now opened via the GALLERY button in the Academy intro) ---------- */
function initGallery(){
  // no-op — gallery button is created dynamically in renderAcademy()
}

/* ---------- Academy tab wiring ---------- */
function initAcademy(){
  const btn = document.getElementById('tabAcademy');
  if(!btn) return;
  btn.addEventListener('click', ()=>switchView('academy'));
  // Expose
  window.fcAcademy = { openExplorer(){ switchView('academy'); A.view='sourceExplorer'; renderAcademy(); } };
}
document.addEventListener('DOMContentLoaded', initAcademy);
document.addEventListener('DOMContentLoaded', initGallery);
if(document.readyState!=='loading') initAcademy();
if(document.readyState!=='loading') initGallery();

})();

/* Boot: enter the Randomiser explicitly. Without this call the body never gets
   rand-mode (the default CSS shows #randView anyway), and every rand-mode-scoped
   behaviour — including the wiki-link click delegation on the randomiser card —
   stays dead until the user clicks a tab. */
if (window.fcSwitchView) window.fcSwitchView('rand');
